            current_state, ensure_ascii=False,
            separators=(",", ":"),
        ).encode("utf-8")
    except UnicodeEncodeError:
        fail(EXIT_INPUT, "INPUT")
    if len(current_bytes) > CHECKPOINT_LIMIT:
        fail(EXIT_OVERLOAD, "OVERLOAD")

    # status：当前与候选规范化 state 逐字节相同为 SAME；否则存在三
    # 份不全相同的冲突段为 CONFLICT；其余为 CLEAN。
    if current_state == target_state:
        status = "SAME"
        changes = []
        conflict_sections = set()
    else:
        changes = []
        conflict_sections = set()
        for section in current_state:
            cur_value = current_state[section]
            base_value = base_state[section]
            tgt_value = target_state[section]
            if cur_value == base_value == tgt_value:
                continue
            # 三份不全相同：分类 kind。
            if cur_value == base_value and tgt_value != base_value:
                # 基线未变、候选单方面变更：候选仍是可快进的目标。
                kind = "TARGET"
            elif tgt_value == base_value and cur_value != base_value:
                # 候选未触及该段、仅当前相对基线变化。
                kind = "CURRENT"
            elif cur_value == tgt_value and base_value != cur_value:
                # 当前与候选一致而基线不同。
                kind = "SAME"
            else:
                kind = "CONFLICT"
                conflict_sections.add(section)
            changes.append(
                {
                    "section": section,
                    "base": section_digest(base_value),
                    "current": section_digest(cur_value),
                    "target": section_digest(tgt_value),
                    "kind": kind,
                }
            )
        status = "CONFLICT" if conflict_sections else "CLEAN"

    # 段分类计数（仅统计三份不全相同的段，即 changes）。
    kind_counts = {"TARGET": 0, "CURRENT": 0, "SAME": 0,
                   "CONFLICT": 0}
    for change in changes:
        kind_counts[change["kind"]] += 1

    results.append(
        {
            "op": "sx",
            "current": {
                "version": CHECKPOINT_VERSION,
                "digest": hashlib.sha256(
                    json.dumps(
                        {"version": CHECKPOINT_VERSION,
                         "state": current_state},
                        ensure_ascii=False, separators=(",", ":"),
                    ).encode("utf-8")
                ).hexdigest(),
                "state": current_state,
            },
            "base": {
                "version": CHECKPOINT_VERSION,
                "digest": base_digest,
                "state": base_state,
            },
            "target": {
                "version": CHECKPOINT_VERSION,
                "digest": target_digest,
                "state": target_state,
            },
            "status": status,
            "changes": changes,
            "summary": {
                "sections": len(current_state),
                "changed": len(changes),
                "target": kind_counts["TARGET"],
                "current": kind_counts["CURRENT"],
                "same": kind_counts["SAME"],
                "conflict": kind_counts["CONFLICT"],
            },
        }
    )

